/* Hostels & PG by Elsha, part 2: rent & fees, mess, gate register, complaints, notices, expenses, reports, enquiries, settings, demo data. */
'use strict';

/* ---------- Rent & fees ---------- */
function hsFees(body, again) {
  hsSubnav(body, 'fees', [['bills', 'Monthly bills'], ['pay', 'Payments'], ['dep', 'Deposits']], (view, el) => {
    const m = Session.get('hsFeeMonth') || hsMonth(), monthPick = `<label class="field" style="max-width:200px"><span>Month</span><input class="input" type="month" id="hs-m" value="${m}"></label>`;
    const bindMonth = () => { const x = $('#hs-m', el); if (x) x.onchange = e => { Session.set('hsFeeMonth', e.target.value || hsMonth()); again(); }; };
    if (view === 'bills') {
      const I = HS.list('invoices').filter(i => i.month === m).sort((a, b) => a.name.localeCompare(b.name)), billed = hsSum(I, i => i.total), bal = hsSum(I, hsInvBal), late = I.filter(i => hsInvState(i) === 'Overdue');
      const unbilled = HS.list('residents').filter(r => ['Active', 'Notice'].includes(r.status) && !I.some(i => i.residentId === r.id && i.lines.some(l => l.type === 'Rent')) && hsMonthLines(r, m).length).length;
      el.innerHTML = `<div class="crud-bar" style="align-items:end">${monthPick}<span class="spacer"></span><button class="btn btn-outline" id="hs-split">Split a room bill</button><button class="btn btn-outline" id="hs-rem" ${late.length ? '' : 'disabled'}>Reminders (${late.length})</button><button class="btn btn-primary" id="hs-gen" ${unbilled ? '' : 'disabled'}>Bill ${unbilled} resident${unbilled === 1 ? '' : 's'} for ${esc(hsMonthName(m))}</button></div>
        <div class="kpis" style="margin:14px 0">${kpi('Billed', inr(billed), `${I.length} bills`)}${kpi('Collected', inr(billed - bal))}${kpi('Balance', inr(bal), '', bal > 0)}${kpi('Overdue', late.length, `after the ${HS.cfg().dueDay}${['st', 'nd', 'rd'][((+HS.cfg().dueDay + 90) % 100 - 10) % 10 - 1] || 'th'}`, late.length > 0)}</div>
        <div class="table-wrap"><table class="table"><thead><tr><th>Resident</th><th>Bed</th><th>Charges</th><th>Total</th><th>Balance</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${I.map(i => { const r = hsRes(i.residentId) || { name: i.name }, s = hsInvState(i), b = hsInvBal(i);
          return `<tr><td><b>${esc(i.name)}</b></td><td>${esc(hsBedLabel(r))}</td><td class="small">${i.lines.map(l => `${esc(l.type)} ${inr(l.amount)}`).join('<br>')}</td><td>${inr(i.total)}</td><td>${b ? `<b>${inr(b)}</b>` : '—'}</td><td>${fmtDate(i.dueDate)}</td><td>${hsInvChip(s)}</td>
            <td class="row-actions">${b ? `<button class="btn btn-sm btn-ghost" data-col="${esc(i.residentId)}">Collect</button>` : ''}<button class="btn btn-sm btn-ghost" data-chg="${esc(i.id)}">+ Charge</button>${s === 'Overdue' && +HS.cfg().lateFee > 0 && !i.lines.some(l => l.type === 'Late fee') ? `<button class="btn btn-sm btn-ghost" data-late="${esc(i.id)}">Late fee</button>` : ''}<button class="btn btn-sm btn-ghost" data-bill="${esc(i.id)}">Print</button>${b && r.phone ? `<a class="btn btn-sm btn-ghost" target="_blank" rel="noopener" href="${hsRemind(r, hsDue(r.id))}">WhatsApp</a>` : ''}${!hsInvPaid(i) ? `<button class="btn btn-sm btn-danger-ghost" data-del="${esc(i.id)}">Delete</button>` : ''}</td></tr>`; }).join('') || `<tr><td colspan="8" class="empty">No bills for ${esc(hsMonthName(m))} yet.${unbilled ? ' Press “Bill … residents”.' : ''}</td></tr>`}</tbody></table></div>
        <p class="muted small" style="margin-top:10px">Bills are counted by the days each resident stays in the month. Mess is added when a mess fee is set in Hostel &amp; settings and the resident takes food. Hostel rent for students and working professionals up to ₹20,000 a month per person is usually GST-free; check with your accountant.</p>`;
      bindMonth();
      $('#hs-gen', el).onclick = () => { const n = hsBillMonth(m); toast(`${n} bill${n === 1 ? '' : 's'} created for ${hsMonthName(m)}`); again(); };
      $('#hs-rem', el).onclick = () => openModal('Send reminders', `<p class="muted small">Tap each name to open WhatsApp with the message ready.</p>${late.map(i => { const r = hsRes(i.residentId); return r ? `<div class="line-item"><span><b>${esc(r.name)}</b> · ${esc(hsBedLabel(r))}</span><a class="btn btn-sm btn-green" target="_blank" rel="noopener" href="${hsRemind(r, hsDue(r.id))}">${inr(hsDue(r.id))} · WhatsApp</a></div>` : ''; }).join('')}`);
      $('#hs-split', el).onclick = () => { const rooms = hsRooms(); openModal('Split a room bill', `<form class="form-grid" id="hs-sp"><label class="field"><span>Room</span><select class="input" name="room">${rooms.map(r => `<option value="${esc(r.id)}">${esc(r.number)}</option>`).join('')}</select></label><label class="field"><span>What for</span><select class="input" name="type"><option>Electricity</option><option>Water</option><option>Laundry</option><option>Maintenance</option><option>Other</option></select></label><label class="field"><span>Total amount (₹)</span><input class="input" type="number" name="amt" min="1" required></label><label class="field"><span>Note</span><input class="input" name="note" placeholder="Meter 1234 → 1310 (76 units)"></label><p class="full muted small" id="hs-sp-who"></p><div class="full" style="display:flex;justify-content:flex-end;gap:10px"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary">Add to their bills</button></div></form>`, { onMount: mm => {
        const f = $('#hs-sp', mm), who = () => HS.list('residents').filter(r => r.roomId === f.room.value && ['Active', 'Notice'].includes(r.status)), show = () => { const w = who(); $('#hs-sp-who', mm).textContent = w.length ? `Shared by ${w.length}: ${w.map(r => r.name).join(', ')}${+f.amt.value ? ` · ${inr(+f.amt.value / w.length)} each` : ''}` : 'No one stays in this room now.'; };
        f.addEventListener('input', show); show();
        f.onsubmit = e => { e.preventDefault(); const w = who(); if (!w.length) return toast('No one stays in this room', 'err'); const each = Math.round(+f.amt.value / w.length), r = HS.find('rooms', f.room.value);
          w.forEach(x => hsInvoiceFor(x, m, [{ type: f.type.value, desc: `${f.type.value} · room ${r.number} shared by ${w.length}${f.note.value.trim() ? ' · ' + f.note.value.trim() : ''}`, amount: each }])); closeModal(); toast(`${inr(each)} added to ${w.length} bills`); again(); }; } }); };
      $$('[data-col]', el).forEach(b => b.onclick = () => hsCollectModal(hsRes(b.dataset.col), again));
      $$('[data-del]', el).forEach(b => b.onclick = () => confirmBox('Delete this bill?', () => { HS.del('invoices', b.dataset.del); again(); }));
      $$('[data-late]', el).forEach(b => b.onclick = () => { const i = HS.find('invoices', b.dataset.late), days = Math.max(1, daysBetween(i.dueDate, todayISO())), fee = days * +HS.cfg().lateFee, lines = [...i.lines, { type: 'Late fee', desc: `Late fee · ${days} day(s)`, amount: fee }]; HS.upd('invoices', i.id, { lines, total: hsTotal(lines) }); toast(`Late fee ${inr(fee)} added`); again(); });
      $$('[data-chg]', el).forEach(b => b.onclick = () => { const i = HS.find('invoices', b.dataset.chg); openModal(`Add a charge · ${i.name}`, `<form class="form-grid" id="hs-ch"><label class="field"><span>Type</span><select class="input" name="type"><option>Electricity</option><option>Laundry</option><option>Fine</option><option>Maintenance</option><option>Guest stay</option><option>Other</option><option>Discount</option></select></label><label class="field"><span>Amount (₹)</span><input class="input" type="number" name="amt" min="1" required></label><label class="field full"><span>Details</span><input class="input" name="desc"></label><div class="full" style="display:flex;justify-content:flex-end;gap:10px"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary">Add</button></div></form>`, { onMount: mm => $('#hs-ch', mm).onsubmit = e => { e.preventDefault(); const f = e.target, amt = f.type.value === 'Discount' ? -Math.abs(+f.amt.value) : +f.amt.value, lines = [...i.lines, { type: f.type.value, desc: f.type.value + (f.desc.value.trim() ? ' · ' + f.desc.value.trim() : ''), amount: amt }]; HS.upd('invoices', i.id, { lines, total: hsTotal(lines) }); closeModal(); toast('Charge added'); again(); } }); });
      $$('[data-bill]', el).forEach(b => b.onclick = () => { const i = HS.find('invoices', b.dataset.bill), r = hsRes(i.residentId) || {}, h = HS.hostel(); openModal('Bill · ' + i.id, `${printBar('bill')}<div class="print-sheet"><section class="copy"><header><div class="ph-brand"><b>${esc(h.name)}</b><span>${esc([h.area, h.city].filter(Boolean).join(', '))}</span><span>${esc(h.phone || '')}</span></div><div class="ph-kind"><b>FEE BILL</b><span>${esc(i.id)} · ${esc(hsMonthName(i.month))}</span></div></header><div class="ph-grid"><div><span>Resident</span><b>${esc(i.name)}</b>${esc(r.phone || '')}</div><div><span>Room / bed</span><b>${esc(hsBedLabel(r))}</b>Due by ${fmtDate(i.dueDate)}</div></div><table class="ph-table"><tr><th>Description</th><th>Amount</th></tr>${i.lines.map(l => `<tr><td>${esc(l.desc)}</td><td>${l.amount < 0 ? '−' : ''}${inr(Math.abs(l.amount))}</td></tr>`).join('')}<tr><th>Total</th><th>${inr(i.total)}</th></tr><tr><td>Paid</td><td>${inr(hsInvPaid(i))}</td></tr><tr><th>Balance</th><th>${inr(hsInvBal(i))}</th></tr></table>${h.upi ? `<p class="small">Pay by UPI to <b>${esc(h.upi)}</b> and share the reference with the office.</p>` : ''}</section></div>`, { wide: true }); });
      return;
    }
    if (view === 'pay') {
      const P = HS.list('payments').filter(p => (p.date || '').startsWith(m)).sort((a, b) => (b.date || '').localeCompare(a.date || '')), by = k => hsSum(P.filter(p => p.method === k && p.kind !== 'Refund'), p => p.amount);
      el.innerHTML = `<div class="crud-bar" style="align-items:end">${monthPick}</div><div class="kpis" style="margin:14px 0">${kpi('Fees received', inr(hsSum(P.filter(p => ['Fee', 'Advance'].includes(p.kind) && p.method !== 'From deposit'), p => p.amount)))}${kpi('Deposits received', inr(hsSum(P.filter(p => p.kind === 'Deposit'), p => p.amount)))}${kpi('Refunds paid', inr(hsSum(P.filter(p => p.kind === 'Refund'), p => p.amount)))}${kpi('Cash · UPI', `${inr(by('Cash'))} · ${inr(by('UPI'))}`)}</div>
        <div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Receipt</th><th>Resident</th><th>For</th><th>Paid by</th><th>Amount</th><th></th></tr></thead><tbody>${P.map(p => `<tr><td>${fmtDate(p.date)}</td><td class="mono small">${esc(p.id)}</td><td>${esc(p.name)}</td><td>${esc(p.kind === 'Fee' ? 'Fees · ' + hsMonthName(p.month || m) : p.kind)}</td><td>${esc(p.method)}${p.ref ? `<div class="muted small">${esc(p.ref)}</div>` : ''}</td><td>${p.kind === 'Refund' ? '−' : ''}${inr(p.amount)}</td><td class="row-actions"><button class="btn btn-sm btn-ghost" data-rc="${esc(p.id)}">Receipt</button>${Auth.user()?.role === 'admin' ? `<button class="btn btn-sm btn-danger-ghost" data-del="${esc(p.id)}">Delete</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="7" class="empty">No payments this month.</td></tr>'}</tbody></table></div>`;
      bindMonth();
      $$('[data-rc]', el).forEach(b => b.onclick = () => hsReceipt([HS.find('payments', b.dataset.rc)]));
      $$('[data-del]', el).forEach(b => b.onclick = () => confirmBox('Delete this payment? The bill it paid becomes due again.', () => { HS.del('payments', b.dataset.del); again(); }));
      return;
    }
    const R = HS.list('residents').map(r => ({ r, d: hsDeposit(r.id) })).filter(x => x.d !== 0 || HS_LIVE.includes(x.r.status));
    el.innerHTML = `<div class="kpis" style="margin-bottom:14px">${kpi('Deposits held', inr(hsSum(R, x => x.d)))}${kpi('Residents with deposit', R.filter(x => x.d > 0).length)}${kpi('Deposit not fully paid', R.filter(x => HS_LIVE.includes(x.r.status) && x.d < (+x.r.deposit || 0)).length)}</div>
      <div class="table-wrap"><table class="table"><thead><tr><th>Resident</th><th>Bed</th><th>Agreed</th><th>Held</th><th>Status</th><th></th></tr></thead><tbody>${R.sort((a, b) => a.r.name.localeCompare(b.r.name)).map(({ r, d }) => `<tr><td><b>${esc(r.name)}</b></td><td>${esc(hsBedLabel(r))}</td><td>${inr(r.deposit)}</td><td>${inr(d)}${d < (+r.deposit || 0) && HS_LIVE.includes(r.status) ? ` <span class="chip warn">${inr((+r.deposit || 0) - d)} short</span>` : ''}</td><td>${statusChip(r.status)}</td><td class="row-actions">${HS_LIVE.includes(r.status) && d < (+r.deposit || 0) ? `<button class="btn btn-sm btn-ghost" data-dep="${esc(r.id)}">Take deposit</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No deposits yet.</td></tr>'}</tbody></table></div>`;
    $$('[data-dep]', el).forEach(b => b.onclick = () => { const r = hsRes(b.dataset.dep), short = (+r.deposit || 0) - hsDeposit(r.id); openModal(`Deposit · ${r.name}`, `<form class="form-grid" id="hs-dp"><label class="field"><span>Amount (₹)</span><input class="input" type="number" name="amt" min="1" value="${short}" required></label><label class="field"><span>Paid by</span><select class="input" name="method">${HS_PAY.map(x => `<option>${x}</option>`).join('')}</select></label><div class="full" style="display:flex;justify-content:flex-end;gap:10px"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary">Save &amp; print receipt</button></div></form>`, { onMount: mm => $('#hs-dp', mm).onsubmit = e => { e.preventDefault(); const p = HS.add('payments', { residentId: r.id, name: r.name, kind: 'Deposit', amount: +e.target.amt.value, method: e.target.method.value, date: todayISO(), ref: '', note: 'Security deposit' }, 'HP'); closeModal(); again(); hsReceipt([p]); } }); });
  });
}

/* ---------- Mess ---------- */
const HS_DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'], HS_MEALS = ['Breakfast', 'Lunch', 'Snacks', 'Dinner'];
function hsMess(body, again) {
  hsSubnav(body, 'mess', [['count', "Today's count"], ['menu', 'Weekly menu']], (view, el) => {
    const key = 'MENU' + HS.H(), menu = Store.get('hs_settings').find(s => s.id === key)?.menu || {};
    if (view === 'menu') {
      el.innerHTML = `<form id="hs-menu"><div class="table-wrap"><table class="table hs-menu"><thead><tr><th>Day</th>${HS_MEALS.map(x => `<th>${x}</th>`).join('')}</tr></thead><tbody>${HS_DAYS.map(d => `<tr><td><b>${d}</b></td>${HS_MEALS.map(x => `<td><input class="input" name="${d}|${x}" value="${esc(menu[d]?.[x] || '')}" placeholder="—"></td>`).join('')}</tr>`).join('')}</tbody></table></div>
        <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:12px"><button type="button" class="btn btn-outline" id="hs-mp">Print menu</button><button class="btn btn-primary">Save menu</button></div></form>`;
      $('#hs-menu', el).onsubmit = e => { e.preventDefault(); const out = {}; $$('input', e.target).forEach(i => { const [d, x] = i.name.split('|'); (out[d] = out[d] || {})[x] = i.value.trim(); }); HS.put('settings', key, { menu: out }); toast('Menu saved'); };
      $('#hs-mp', el).onclick = () => openModal('Weekly menu', `${printBar('menu')}<div class="print-sheet"><section class="copy"><header><div class="ph-brand"><b>${esc(HS.hostel().name)}</b><span>Mess menu</span></div><div class="ph-kind"><b>WEEKLY MENU</b><span>from ${fmtDate(todayISO())}</span></div></header><table class="ph-table"><tr><th>Day</th>${HS_MEALS.map(x => `<th>${x}</th>`).join('')}</tr>${HS_DAYS.map(d => `<tr><td><b>${d}</b></td>${HS_MEALS.map(x => `<td>${esc(menu[d]?.[x] || '—')}</td>`).join('')}</tr>`).join('')}</table></section></div>`, { wide: true });
      return;
    }
    const t = todayISO(), day = HS_DAYS[(new Date(t + 'T00:00:00').getDay() + 6) % 7], eat = HS.list('residents').filter(r => ['Active', 'Notice'].includes(r.status) && r.mess);
    const away = new Set(HS.list('outings').filter(o => !o.backAt && o.type !== 'Outing').map(o => o.residentId)), roll = Store.get('hs_roll').find(x => x.id === `${HS.H()}_${t}`)?.marks || {};
    const here = eat.filter(r => !away.has(r.id) && !['L', 'A'].includes(roll[r.id])), food = k => here.filter(r => (r.food || 'Veg') === k).length;
    el.innerHTML = `<div class="kpis">${kpi('Eating today', here.length, `${eat.length - here.length} away / on leave`)}${kpi('Veg', food('Veg'))}${kpi('Non-veg', food('Non-veg'))}${kpi('Egg', food('Egg'))}</div>
      <div class="grid g2" style="margin-top:18px"><div class="card"><h3 style="margin-bottom:10px">${day}'s menu</h3>${HS_MEALS.map(x => `<div class="line-item"><span>${x}</span><b>${esc(menu[day]?.[x] || '—')}</b></div>`).join('')}<p class="muted small" style="margin-top:8px">Edit in Weekly menu.</p></div>
      <div class="card"><h3 style="margin-bottom:10px">Not eating today</h3>${eat.filter(r => !here.includes(r)).map(r => `<div class="line-item"><span>${esc(r.name)}</span><span class="muted small">${away.has(r.id) ? 'away' : 'on leave / absent'}</span></div>`).join('') || '<p class="muted">Everyone who takes food is in.</p>'}</div></div>`;
    void again;
  });
}

/* ---------- Gate register: outings & leave, night roll call, visitors ---------- */
function hsGate(body, again) {
  hsSubnav(body, 'gate', [['out', 'Outings & leave'], ['roll', 'Night roll call'], ['vis', 'Visitors']], (view, el) => {
    const live = HS.list('residents').filter(r => ['Active', 'Notice'].includes(r.status)).sort((a, b) => a.name.localeCompare(b.name)), nowLocal = hsLocalNow;
    if (view === 'out') {
      const O = HS.list('outings').sort((a, b) => (b.outAt || '').localeCompare(a.outAt || '')), open = O.filter(o => !o.backAt), done = O.filter(o => o.backAt).slice(0, 40);
      el.innerHTML = `<div class="crud-bar"><span class="muted small">${open.length} resident(s) out now · gate closes at ${esc(HS.cfg().gateTime)}</span><span class="spacer"></span><button class="btn btn-primary" id="hs-go">+ Resident going out</button></div>
        <div class="table-wrap"><table class="table"><thead><tr><th>Resident</th><th>Type</th><th>Went out</th><th>Expected back</th><th>Where / why</th><th></th></tr></thead><tbody>${open.map(o => { const late = o.expectedBack && o.expectedBack < nowLocal(); return `<tr><td><b>${esc(hsRes(o.residentId)?.name || o.name)}</b><div class="muted small">${esc(hsBedLabel(hsRes(o.residentId)))}</div></td><td>${esc(o.type)}${o.parentOk ? ' <span class="chip green">parent OK</span>' : ''}</td><td>${fmtDateTime(o.outAt)}</td><td>${o.expectedBack ? fmtDateTime(o.expectedBack) : '—'} ${late ? '<span class="chip danger">late</span>' : ''}</td><td class="small">${esc(o.purpose || '')}</td><td class="row-actions"><button class="btn btn-sm btn-ghost" data-back="${esc(o.id)}">Back in</button>${late && hsRes(o.residentId) ? `<a class="btn btn-sm btn-ghost" href="tel:${esc(hsRes(o.residentId).phone)}">Call</a>` : ''}</td></tr>`; }).join('') || '<tr><td colspan="6" class="empty">Everyone is in.</td></tr>'}</tbody></table></div>
        <h3 style="margin:18px 0 10px">Recent returns</h3><div class="table-wrap"><table class="table"><thead><tr><th>Resident</th><th>Type</th><th>Out</th><th>Back</th><th></th></tr></thead><tbody>${done.map(o => `<tr><td>${esc(hsRes(o.residentId)?.name || o.name)}</td><td>${esc(o.type)}</td><td>${fmtDateTime(o.outAt)}</td><td>${fmtDateTime(o.backAt)}</td><td>${o.late ? '<span class="chip warn">came back late</span>' : ''}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">Nothing yet.</td></tr>'}</tbody></table></div>`;
      $('#hs-go', el).onclick = () => openModal('Resident going out', `<form class="form-grid" id="hs-out"><label class="field full"><span>Resident</span><select class="input" name="res" required><option value="">Choose</option>${live.filter(r => !HS.list('outings').some(o => !o.backAt && o.residentId === r.id)).map(r => `<option value="${esc(r.id)}">${esc(r.name)} · ${esc(hsBedLabel(r))}</option>`).join('')}</select></label>
        <label class="field"><span>Type</span><select class="input" name="type"><option>Outing</option><option>Night out</option><option>Home leave</option><option>College / office trip</option><option>Medical</option></select></label><label class="field"><span>Going out at</span><input class="input" type="datetime-local" name="out" value="${nowLocal()}" required></label>
        <label class="field"><span>Expected back</span><input class="input" type="datetime-local" name="back" value="${todayISO()}T${esc(HS.cfg().gateTime)}"></label><label class="field"><span>Where / why</span><input class="input" name="purpose"></label><label class="check full"><input type="checkbox" name="parentOk"> Parent / guardian informed and agreed</label>
        <div class="full" style="display:flex;justify-content:flex-end;gap:10px"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary">Save</button></div></form>`, { onMount: m => $('#hs-out', m).onsubmit = e => { e.preventDefault(); const f = e.target, r = hsRes(f.res.value); if (!r) return toast('Choose the resident', 'err');
          HS.add('outings', { residentId: r.id, name: r.name, type: f.type.value, outAt: f.out.value, expectedBack: f.back.value, purpose: f.purpose.value.trim(), parentOk: f.parentOk.checked, backAt: '' }, 'HO'); closeModal(); toast(`${r.name} marked out`); again(); } });
      $$('[data-back]', el).forEach(b => b.onclick = () => { const o = HS.find('outings', b.dataset.back), t = nowLocal(); HS.upd('outings', o.id, { backAt: t, late: !!(o.expectedBack && t > o.expectedBack) }); toast('Marked back in'); again(); });
      return;
    }
    if (view === 'roll') {
      const date = Session.get('hsRollDate') || todayISO(), id = `${HS.H()}_${date}`, saved = Store.get('hs_roll').find(x => x.id === id), marks = { ...(saved?.marks || {}) }, out = new Set(HS.list('outings').filter(o => !o.backAt).map(o => o.residentId));
      live.forEach(r => { if (!marks[r.id] && out.has(r.id)) marks[r.id] = 'O'; });
      const K = { P: 'Present', A: 'Absent', L: 'On leave', O: 'Out (in register)' };
      el.innerHTML = `<div class="crud-bar" style="align-items:end"><label class="field" style="max-width:200px"><span>Date</span><input class="input" type="date" id="hs-rd" value="${date}" max="${todayISO()}"></label><span class="spacer"></span><button class="btn btn-outline" id="hs-allp">Everyone else present</button><button class="btn btn-primary" id="hs-rs">Save roll call</button></div>
        <p class="muted small" style="margin:8px 0">${saved ? `Saved by ${esc(saved.by || '')} at ${fmtDateTime(saved.at)}.` : 'Not taken yet for this date.'} Residents out in the register are marked “Out” for you.</p>
        <div class="table-wrap"><table class="table"><thead><tr><th>Resident</th><th>Bed</th><th>Roll call</th><th></th></tr></thead><tbody>${live.map(r => `<tr data-r="${esc(r.id)}"><td><b>${esc(r.name)}</b></td><td>${esc(hsBedLabel(r))}</td><td><div class="chips">${Object.entries(K).map(([k, l]) => `<button type="button" class="chip ${marks[r.id] === k ? 'on' : ''}" data-k="${k}" title="${l}">${k === 'O' ? 'Out' : l}</button>`).join('')}</div></td><td>${marks[r.id] === 'A' ? `<a class="btn btn-sm btn-ghost" target="_blank" rel="noopener" href="${hsWa(r.guardianPhone, `Dear ${r.guardian || 'parent'}, ${r.name} was not in ${HS.hostel().name} at the night roll call on ${fmtDate(date)}. Please call the hostel office.`)}">Tell parent</a>` : ''}</td></tr>`).join('') || '<tr><td colspan="4" class="empty">No residents.</td></tr>'}</tbody></table></div>`;
      $('#hs-rd', el).onchange = e => { Session.set('hsRollDate', e.target.value || todayISO()); again(); };
      $$('tr[data-r]', el).forEach(tr => $$('[data-k]', tr).forEach(b => b.onclick = () => { marks[tr.dataset.r] = b.dataset.k; $$('[data-k]', tr).forEach(x => x.classList.toggle('on', x === b)); }));
      $('#hs-allp', el).onclick = () => live.forEach(r => { if (!marks[r.id]) { marks[r.id] = 'P'; $$(`tr[data-r="${r.id}"] [data-k]`, el).forEach(x => x.classList.toggle('on', x.dataset.k === 'P')); } });
      $('#hs-rs', el).onclick = () => { const doc = { id, hostelId: HS.H(), date, marks, by: Auth.user()?.name || '', at: hsNow() }; Store.find('hs_roll', id) ? Store.update('hs_roll', id, doc) : Store.add('hs_roll', doc); const a = Object.values(marks).filter(x => x === 'A').length; toast(`Roll call saved${a ? ` · ${a} absent` : ''}`); again(); };
      return;
    }
    const V = HS.list('visitors').sort((a, b) => (b.inAt || '').localeCompare(a.inAt || '')), inside = V.filter(v => !v.outAt);
    el.innerHTML = `<div class="crud-bar"><span class="muted small">${inside.length} visitor(s) inside now</span><span class="spacer"></span><button class="btn btn-primary" id="hs-vin">+ Visitor in</button></div>
      <div class="table-wrap"><table class="table"><thead><tr><th>Visitor</th><th>Meeting</th><th>In</th><th>Out</th><th>ID</th><th></th></tr></thead><tbody>${V.slice(0, 60).map(v => `<tr><td><b>${esc(v.name)}</b><div class="muted small">${esc(v.phone)} · ${esc(v.relation)}</div></td><td>${esc(hsRes(v.residentId)?.name || '')}<div class="muted small">${esc(v.purpose || '')}</div></td><td>${fmtDateTime(v.inAt)}</td><td>${v.outAt ? fmtDateTime(v.outAt) : '<span class="chip blue">inside</span>'}</td><td class="small">${esc(v.idProof || '')}</td><td class="row-actions">${v.outAt ? '' : `<button class="btn btn-sm btn-ghost" data-vout="${esc(v.id)}">Left</button>`}</td></tr>`).join('') || '<tr><td colspan="6" class="empty">No visitors yet.</td></tr>'}</tbody></table></div>`;
    $('#hs-vin', el).onclick = () => openModal('Visitor in', `<form class="form-grid" id="hs-vf"><label class="field"><span>Visitor name</span><input class="input" name="name" required></label><label class="field"><span>Mobile</span><input class="input" name="phone" required></label><label class="field"><span>Meeting</span><select class="input" name="res" required><option value="">Choose resident</option>${live.map(r => `<option value="${esc(r.id)}">${esc(r.name)} · ${esc(hsBedLabel(r))}</option>`).join('')}</select></label><label class="field"><span>Relation</span><select class="input" name="relation"><option>Parent</option><option>Sibling</option><option>Relative</option><option>Friend</option><option>Delivery / service</option><option>Other</option></select></label><label class="field"><span>ID shown</span><input class="input" name="idProof" placeholder="Aadhaar XXXX 1234"></label><label class="field"><span>Purpose</span><input class="input" name="purpose"></label><div class="full" style="display:flex;justify-content:flex-end;gap:10px"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary">Save</button></div></form>`, { onMount: m => $('#hs-vf', m).onsubmit = e => { e.preventDefault(); const f = e.target; HS.add('visitors', { name: f.name.value.trim(), phone: f.phone.value.trim(), residentId: f.res.value, relation: f.relation.value, idProof: f.idProof.value.trim(), purpose: f.purpose.value.trim(), inAt: hsNow(), outAt: '' }, 'HV'); closeModal(); toast('Visitor entered'); again(); } });
    $$('[data-vout]', el).forEach(b => b.onclick = () => { HS.upd('visitors', b.dataset.vout, { outAt: hsNow() }); again(); });
  });
}

/* ---------- Complaints, notices, expenses ---------- */
function hsComplaints(body, again) {
  const live = () => HS.list('residents').filter(r => HS_LIVE.includes(r.status)), C = HS.list('complaints');
  hsCrud(body, 'complaints', { single: 'Complaint', plural: 'Complaints', idPrefix: 'HC', label: r => r.category,
    rows: () => HS.list('complaints').sort((a, b) => (a.status === 'Resolved') - (b.status === 'Resolved') || (b.createdAt || '').localeCompare(a.createdAt || '')),
    toolbar: `<span class="muted small">${C.filter(c => c.status !== 'Resolved').length} open · ${C.filter(c => c.status !== 'Resolved' && c.priority === 'Urgent').length} urgent</span>`,
    fields: () => [{ name: 'residentId', label: 'Raised by', type: 'select', options: [['', 'Staff / common area'], ...live().map(r => [r.id, `${r.name} · ${hsBedLabel(r)}`])] }, { name: 'category', label: 'Category', type: 'select', options: ['Electrical', 'Plumbing', 'Cleaning', 'Wi-Fi / internet', 'Food / mess', 'Furniture', 'Water', 'Security', 'Noise / behaviour', 'Other'] }, { name: 'priority', label: 'Priority', type: 'select', options: ['Normal', 'High', 'Urgent'] }, { name: 'status', label: 'Status', type: 'select', options: ['Open', 'In progress', 'Resolved'] }, { name: 'assigned', label: 'Assigned to', placeholder: 'Electrician Ravi' }, { name: 'place', label: 'Where', placeholder: 'Room 204 / 2nd floor bathroom' }, { name: 'detail', label: 'What is wrong', full: true, required: true }, { name: 'resolution', label: 'What was done', full: true }],
    transform: (d, row) => { if (d.status === 'Resolved' && row?.status !== 'Resolved') d.resolvedAt = hsNow(); },
    columns: [{ label: 'Complaint', render: r => `<b>${esc(r.category)}</b><div class="small">${esc(r.detail)}</div>` }, { label: 'From', render: r => esc(hsRes(r.residentId)?.name || 'Staff') + `<div class="muted small">${esc(r.place || hsBedLabel(hsRes(r.residentId)))}</div>` }, { label: 'Priority', render: r => `<span class="chip ${r.priority === 'Urgent' ? 'danger' : r.priority === 'High' ? 'warn' : ''}">${esc(r.priority)}</span>` }, { label: 'Raised', render: r => fmtDateTime(r.createdAt) }, { label: 'Status', render: r => `<span class="chip ${r.status === 'Resolved' ? 'green' : r.status === 'Open' ? 'danger' : 'warn'}">${esc(r.status)}</span>${r.assigned ? `<div class="muted small">${esc(r.assigned)}</div>` : ''}` }],
    actions: [{ id: 'go', label: 'Start', show: r => r.status === 'Open', run: (r, rr) => { HS.upd('complaints', r.id, { status: 'In progress' }); rr(); } }, { id: 'ok', label: 'Resolved', show: r => r.status !== 'Resolved', run: (r, rr) => { HS.upd('complaints', r.id, { status: 'Resolved', resolvedAt: hsNow() }); toast('Marked resolved'); rr(); } }] });
  void again;
}
function hsNotices(body) {
  hsCrud(body, 'notices', { single: 'Notice', plural: 'Notices', idPrefix: 'HN', label: r => r.title, rows: () => HS.list('notices').sort((a, b) => (b.date || '').localeCompare(a.date || '')),
    fields: [{ name: 'title', label: 'Title', required: true }, { name: 'date', label: 'Date', type: 'date', default: todayISO() }, { name: 'for', label: 'For', type: 'select', options: ['All residents', 'Students', 'Working professionals', 'Parents', 'Staff'] }, { name: 'msg', label: 'Message', type: 'textarea', full: true, required: true }],
    columns: [{ label: 'Notice', render: r => `<b>${esc(r.title)}</b><div class="small">${esc(r.msg)}</div>` }, { label: 'For', field: 'for' }, { label: 'Date', render: r => fmtDate(r.date) }],
    actions: [{ id: 'wa', label: 'Share on WhatsApp', run: r => window.open(`https://wa.me/?text=${encodeURIComponent(`📢 ${HS.hostel().name}: ${r.title}\n${r.msg}`)}`, '_blank', 'noopener') }, { id: 'pr', label: 'Print', run: r => openModal('Notice', `${printBar('notice')}<div class="print-sheet"><section class="copy"><header><div class="ph-brand"><b>${esc(HS.hostel().name)}</b><span>Notice board</span></div><div class="ph-kind"><b>NOTICE</b><span>${fmtDate(r.date)}</span></div></header><h2 style="margin:8px 0">${esc(r.title)}</h2><p style="white-space:pre-wrap;font-size:15px">${esc(r.msg)}</p><p class="small">For: ${esc(r.for)} · Warden / Office</p></section></div>`, { wide: true }) }] });
}
const HS_EXP = ['Groceries / mess', 'Gas', 'Electricity', 'Water', 'Salary', 'Building rent', 'Maintenance & repairs', 'Housekeeping supplies', 'Internet', 'Laundry', 'Taxes & licences', 'Marketing', 'Other'];
function hsExpenses(body, again) {
  const m = Session.get('hsExpMonth') || hsMonth(), E = HS.list('expenses').filter(e => (e.date || '').startsWith(m)), inc = hsSum(HS.list('payments').filter(p => ['Fee', 'Advance'].includes(p.kind) && p.method !== 'From deposit' && (p.date || '').startsWith(m)), p => p.amount), out = hsSum(E, e => e.amount);
  body.innerHTML = `<div class="crud-bar" style="align-items:end"><label class="field" style="max-width:200px"><span>Month</span><input class="input" type="month" id="hs-em" value="${m}"></label></div><div class="kpis" style="margin:14px 0">${kpi('Fees received', inr(inc))}${kpi('Expenses', inr(out))}${kpi(inc - out >= 0 ? 'Surplus' : 'Shortfall', inr(Math.abs(inc - out)), '', inc - out < 0)}</div><div id="hs-ex"></div>`;
  $('#hs-em', body).onchange = e => { Session.set('hsExpMonth', e.target.value || hsMonth()); again(); };
  hsCrud($('#hs-ex', body), 'expenses', { single: 'Expense', plural: 'Expenses', idPrefix: 'HE', label: r => r.category, rows: () => HS.list('expenses').filter(e => (e.date || '').startsWith(m)).sort((a, b) => b.date.localeCompare(a.date)), onChange: again,
    fields: [{ name: 'date', label: 'Date', type: 'date', default: m === hsMonth() ? todayISO() : m + '-01', required: true }, { name: 'category', label: 'Category', type: 'select', options: HS_EXP }, { name: 'amount', label: 'Amount (₹)', type: 'number', min: 0, required: true }, { name: 'paidTo', label: 'Paid to' }, { name: 'method', label: 'Paid by', type: 'select', options: HS_PAY }, { name: 'bill', label: 'Bill no.' }, { name: 'note', label: 'Note', full: true }],
    columns: [{ label: 'Date', render: r => fmtDate(r.date) }, { label: 'Category', field: 'category' }, { label: 'Paid to', render: r => esc(r.paidTo || '') + (r.note ? `<div class="muted small">${esc(r.note)}</div>` : '') }, { label: 'Paid by', field: 'method' }, { label: 'Amount', render: r => inr(r.amount) }] });
}

/* ---------- Reports ---------- */
function hsReports(body, again) {
  const m = Session.get('hsRepMonth') || hsMonth(), R = HS.list('residents'), B = hsAllBeds(), live = R.filter(r => ['Active', 'Notice'].includes(r.status));
  const pay = HS.list('payments'), inc = hsSum(pay.filter(p => ['Fee', 'Advance'].includes(p.kind) && p.method !== 'From deposit' && (p.date || '').startsWith(m)), p => p.amount), E = HS.list('expenses').filter(e => (e.date || '').startsWith(m)), out = hsSum(E, e => e.amount);
  const open = HS.list('invoices').filter(i => hsInvBal(i) > 0), age = d => { const n = daysBetween(d, todayISO()); return n <= 0 ? 'Not due yet' : n <= 30 ? '1–30 days late' : n <= 60 ? '31–60 days late' : 'Over 60 days late'; };
  const buckets = ['Not due yet', '1–30 days late', '31–60 days late', 'Over 60 days late'].map(k => [k, hsSum(open.filter(i => age(i.dueDate) === k), hsInvBal)]);
  const byCat = Object.entries(E.reduce((o, e) => (o[e.category] = (o[e.category] || 0) + +e.amount, o), {})).sort((a, b) => b[1] - a[1]);
  const months = [5, 4, 3, 2, 1, 0].map(n => hsAddMonths(m, -n));
  const sheet = `<div class="ph-grid"><div><span>Beds</span><b>${B.filter(b => ['occupied', 'notice'].includes(b.state)).length} occupied of ${B.length}</b>${B.filter(b => b.state === 'vacant').length} free · ${B.filter(b => b.state === 'reserved').length} reserved</div><div><span>Residents</span><b>${live.length} staying</b>${live.filter(r => r.kind === 'Student').length} students · ${live.filter(r => r.kind === 'Working professional').length} working · joined this month ${R.filter(r => (r.joinDate || '').startsWith(m)).length} · left ${R.filter(r => (r.vacateDate || '').startsWith(m)).length}</div></div>
    <table class="ph-table"><tr><th>Money · ${esc(hsMonthName(m))}</th><th>Amount</th></tr><tr><td>Billed this month</td><td>${inr(hsSum(HS.list('invoices').filter(i => i.month === m), i => i.total))}</td></tr><tr><td>Fees received</td><td>${inr(inc)}</td></tr><tr><td>Expenses</td><td>${inr(out)}</td></tr><tr><th>${inc - out >= 0 ? 'Surplus' : 'Shortfall'}</th><th>${inr(Math.abs(inc - out))}</th></tr><tr><td>Deposits held (all residents)</td><td>${inr(hsSum(R, r => hsDeposit(r.id)))}</td></tr></table>
    <table class="ph-table"><tr><th>Dues by age</th><th>Amount</th></tr>${buckets.map(([k, v]) => `<tr><td>${k}</td><td>${inr(v)}</td></tr>`).join('')}<tr><th>Total dues</th><th>${inr(hsSum(open, hsInvBal))}</th></tr></table>
    <table class="ph-table"><tr><th>Expenses by category</th><th>Amount</th></tr>${byCat.map(([k, v]) => `<tr><td>${esc(k)}</td><td>${inr(v)}</td></tr>`).join('') || '<tr><td colspan="2">None recorded.</td></tr>'}</table>`;
  body.innerHTML = `<div class="crud-bar" style="align-items:end"><label class="field" style="max-width:200px"><span>Month</span><input class="input" type="month" id="hs-rm" value="${m}"></label><span class="spacer"></span><button class="btn btn-primary" id="hs-rp">Print monthly report</button></div>
    <div class="grid g2" style="margin-top:14px"><div class="card"><h3 style="margin-bottom:12px">Fees received · 6 months</h3>${bars(months.map(x => { const v = hsSum(pay.filter(p => ['Fee', 'Advance'].includes(p.kind) && p.method !== 'From deposit' && (p.date || '').startsWith(x)), p => p.amount); return [hsMonthName(x).slice(0, 3), v, inr(v)]; }))}</div><div class="card"><h3 style="margin-bottom:12px">Expenses · 6 months</h3>${bars(months.map(x => { const v = hsSum(HS.list('expenses').filter(e => (e.date || '').startsWith(x)), e => e.amount); return [hsMonthName(x).slice(0, 3), v, inr(v)]; }))}</div></div>
    <div class="card" style="margin-top:18px">${sheet}</div>`;
  $('#hs-rm', body).onchange = e => { Session.set('hsRepMonth', e.target.value || hsMonth()); again(); };
  $('#hs-rp', body).onclick = () => openModal('Monthly report', `${printBar('report')}<div class="print-sheet"><section class="copy"><header><div class="ph-brand"><b>${esc(HS.hostel().name)}</b><span>${esc(HS.hostel().city || '')}</span></div><div class="ph-kind"><b>MONTHLY REPORT</b><span>${esc(hsMonthName(m))}</span></div></header>${sheet}<div class="ph-sign"><div><span>Warden</span><i></i></div><div><span>Owner</span><i></i></div></div></section></div>`, { wide: true });
}

